				jw_.beginRow();
				jw_.rowNum(r.x);
				jw_.rowNum(r.y);
				jw_.rowNum(r.z);
				jw_.rowNum(r.nx);
				jw_.rowNum(r.ny);
				jw_.rowNum(r.nz);
